EXPLAIN
SELECT user_id, val, SUM(val) OVER (PARTITION BY user_id ORDER BY ts ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS rolling
FROM events;
+---------------+----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+
| plan_type     | plan                                                                                                                                                                                                                             |
+---------------+----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+
| logical_plan  | WindowAggr: [sum(val)]                                                                                                                                                                                                           |
|               |   TableScan: events                                                                                                                                                                                                              |
| physical_plan | BoundedWindowAggExec: wdw=[sum(val): Field { name: "sum" }, frame: WindowFrame { units: Rows }], mode=[Sorted]                                                                                                                    |
|               |   DataSourceExec: file_groups={2 groups: [[t1.parquet], [t2.parquet]]}, projection=[user_id, ts, val], file_type=parquet                                                                                                          |
|               |                                                                                                                                                                                                                                  |
+---------------+----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+
